insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"maya_a_caught","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_bee_fixed","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_bee_stole_b","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_butterflies_calm","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_butterfly_f_chaos","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_c_lesson_done","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_c_restored","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_cat_squished_c","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_dog_ate_d","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_dog_sorry","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_egg_hatched_e","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_g_genius_done","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_gate_opens_g","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_genius_gate_locked","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_giant_egg","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_graduation_intro","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_hat_found_h","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_island_sorted","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_letter_island_chaos","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_lost_hat_h","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_welcome_runaway_a","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}},{"key":"maya_word_hero_graduation","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\teacher_maya.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"maya_a_caught","locale":"he","line_order":0,"content":"וואו! תפסתם את האות <strong>A</strong>! היא כבר לא בורחת.","line_format":"safe_rich_text"},{"dialogue_key":"maya_a_caught","locale":"he","line_order":1,"content":"מעולה! <strong>A</strong> היא האות הראשונה — כמו <strong>Apple</strong> (תפוח) ו-<strong>Ant</strong> (נמלה).","line_format":"safe_rich_text"},{"dialogue_key":"maya_a_caught","locale":"he","line_order":2,"content":"קחו את האות <strong>A</strong> לתיק שלכם. מחר נמשיך לאות הבאה!","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_fixed","locale":"he","line_order":0,"content":"הדבורים חזרו לזמזם! <strong>BEE</strong> שוב נכתב נכון.","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_fixed","locale":"he","line_order":1,"content":"זכרו: <strong>B</strong> היא האות השנייה — כמו <strong>Ball</strong> (כדור) ו-<strong>Book</strong> (ספר).","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_fixed","locale":"he","line_order":2,"content":"כל הכבוד! האות <strong>B</strong> שלכם.","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_stole_b","locale":"he","line_order":0,"content":"עזרה! דבורה שובבה גנבה את האות <strong>B</strong> מהשלט <strong>BEE</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_stole_b","locale":"he","line_order":1,"content":"בלי <strong>B</strong>, הדבורים שוכחות איך לזמזם באנגלית — הן רק עושות 'zzz'.","line_format":"safe_rich_text"},{"dialogue_key":"maya_bee_stole_b","locale":"he","line_order":2,"content":"לכו לשדרת האלף-בית, הביסו את רפש האותיות, וציירו את <strong>B</strong> מחדש!","line_format":"safe_rich_text"},{"dialogue_key":"maya_butterflies_calm","locale":"he","line_order":0,"content":"הפרפרים נרגעו! השלטים חזרו להיות נכונים.","line_format":"plain_text"},{"dialogue_key":"maya_butterflies_calm","locale":"he","line_order":1,"content":"<strong>F</strong> היא האות השישית — כמו <strong>Fish</strong> (דג) ו-<strong>Fun</strong> (כיף).","line_format":"safe_rich_text"},{"dialogue_key":"maya_butterflies_calm","locale":"he","line_order":2,"content":"אבל לא <strong>Fry</strong> — צ'יפס לא אמור לעוף.","line_format":"safe_rich_text"},{"dialogue_key":"maya_butterfly_f_chaos","locale":"he","line_order":0,"content":"פרפרים עם אות <strong>F</strong> על הכנפיים מסביב לגן!","line_format":"safe_rich_text"},{"dialogue_key":"maya_butterfly_f_chaos","locale":"he","line_order":1,"content":"כל פעם שהם נוחתים על שלט, הם משנים אותו ל-<strong>FLY</strong> (לעוף) או <strong>FRY</strong> (לטגן)!","line_format":"safe_rich_text"},{"dialogue_key":"maya_butterfly_f_chaos","locale":"he","line_order":2,"content":"הילדים בגן חושבים שצ'יפס יכול לעוף. עזרו לי — לכו לגן, הביסו את הרפש, וציירו את <strong>F</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_c_lesson_done","locale":"he","line_order":0,"content":"מצוין! <strong>C</strong> היא האות השלישית — כמו <strong>Cat</strong> (חתול) ו-<strong>Cake</strong> (עוגה).","line_format":"safe_rich_text"},{"dialogue_key":"maya_c_lesson_done","locale":"he","line_order":1,"content":"החתול שלי הוא דוגמה מושלמת ל-<strong>C</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_c_restored","locale":"he","line_order":0,"content":"תודה! האות <strong>C</strong> חזרה לצורה המקורית — עגולה ויפה.","line_format":"safe_rich_text"},{"dialogue_key":"maya_c_restored","locale":"he","line_order":1,"content":"<strong>Mittens</strong> מתנצל. הוא הבטיח שלא ישב על אותיות יותר.","line_format":"safe_rich_text"},{"dialogue_key":"maya_cat_squished_c","locale":"he","line_order":0,"content":"אוי לא! החתול שלי, <strong>Mittens</strong>, ישב על האות <strong>C</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_cat_squished_c","locale":"he","line_order":1,"content":"הוא כיווץ אותה לצורת קרואסון — עכשיו כולם קוראים לה 'כרוסון' במקום <strong>C</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"maya_cat_squished_c","locale":"he","line_order":2,"content":"לכו לגן האותיות, ציירו את <strong>C</strong> מחדש, והביאו אותה אליי!","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_ate_d","locale":"he","line_order":0,"content":"הכלב שלי, <strong>Buddy</strong>, אכל את האות <strong>D</strong> משיעורי הבית!","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_ate_d","locale":"he","line_order":1,"content":"עכשיו המילה <strong>dog</strong> נראית כמו <strong>_og</strong> — והכלב עדיין מקיא אותיות!","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_ate_d","locale":"he","line_order":2,"content":"לכו לפינת כלבי הבית, שחקו בהתאמת מילים, ומצאו את <strong>D</strong> בבטן של <strong>Buddy</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_sorry","locale":"he","line_order":0,"content":"<strong>Buddy</strong> מתנצל! הוא הבטיח לא לאכול אותיות יותר.","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_sorry","locale":"he","line_order":1,"content":"מעולה! <strong>D</strong> היא האות הרביעית — כמו <strong>Dog</strong> (כלב) ו-<strong>Door</strong> (דלת).","line_format":"safe_rich_text"},{"dialogue_key":"maya_dog_sorry","locale":"he","line_order":2,"content":"המילה <strong>dog</strong> חזרה להיראות נכון!","line_format":"safe_rich_text"},{"dialogue_key":"maya_egg_hatched_e","locale":"he","line_order":0,"content":"הביצה נפתחה! ובפנים — לא תרנגולת, אלא האות <strong>E</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_egg_hatched_e","locale":"he","line_order":1,"content":"כמו שחשבתי. <strong>E</strong> היא האות החמישית — כמו <strong>Egg</strong> (ביצה) ו-<strong>Elephant</strong> (פיל).","line_format":"safe_rich_text"},{"dialogue_key":"maya_g_genius_done","locale":"he","line_order":0,"content":"מעולה! <strong>G</strong> היא האות השביעית — כמו <strong>Gate</strong> (שער) ו-<strong>Good</strong> (טוב).","line_format":"safe_rich_text"},{"dialogue_key":"maya_g_genius_done","locale":"he","line_order":1,"content":"השער הגאון מבטיח שלא יינעל עליכם שוב.","line_format":"plain_text"},{"dialogue_key":"maya_gate_opens_g","locale":"he","line_order":0,"content":"השער נפתח! הוא אפילו אמר 'תודה' — גאון אמיתי.","line_format":"plain_text"},{"dialogue_key":"maya_gate_opens_g","locale":"he","line_order":1,"content":"האות <strong>G</strong> עשתה את הקסם.","line_format":"safe_rich_text"},{"dialogue_key":"maya_genius_gate_locked","locale":"he","line_order":0,"content":"שער הגאון נעול! הוא אומר שהוא 'גאון', אבל לא יודע לפתוח את עצמו.","line_format":"plain_text"},{"dialogue_key":"maya_genius_gate_locked","locale":"he","line_order":1,"content":"הוא מבקש את האות <strong>G</strong> ושלוש מילים קלות באנגלית.","line_format":"safe_rich_text"},{"dialogue_key":"maya_genius_gate_locked","locale":"he","line_order":2,"content":"לכו לשער הגאון, שחקו בהתאמת מילים, ותביאו לי את <strong>G</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_giant_egg","locale":"he","line_order":0,"content":"יש ביצה ענקית שחוסמת את שער הגן!","line_format":"plain_text"},{"dialogue_key":"maya_giant_egg","locale":"he","line_order":1,"content":"הביצה רוצה לשמוע את האות <strong>E</strong> לפני שהיא נפתחת.","line_format":"safe_rich_text"},{"dialogue_key":"maya_giant_egg","locale":"he","line_order":2,"content":"לכו לשער הגן, סדרו את האותיות במשחק, ותנו לביצה את מה שהיא רוצה!","line_format":"plain_text"},{"dialogue_key":"maya_graduation_intro","locale":"he","line_order":0,"content":"הגעתם למבחן הסיום של ממלכת האנגלית!","line_format":"plain_text"},{"dialogue_key":"maya_graduation_intro","locale":"he","line_order":1,"content":"האות האחרונה היא <strong>J</strong> — כמו <strong>Jump</strong> (לקפוץ) ו-<strong>Joy</strong> (שמחה).","line_format":"safe_rich_text"},{"dialogue_key":"maya_graduation_intro","locale":"he","line_order":2,"content":"לכו לכיכר ההד, ציירו את <strong>J</strong>, ואמרו אותה בקול רם!","line_format":"safe_rich_text"},{"dialogue_key":"maya_graduation_intro","locale":"he","line_order":3,"content":"אני מבטיחה שאין מבחן הפתעה... (יש מבחן הפתעה.)","line_format":"plain_text"},{"dialogue_key":"maya_hat_found_h","locale":"he","line_order":0,"content":"מצאתם את <strong>H</strong>! הכובע שלי חזר — <strong>HAT</strong> ולא <strong>_AT</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"maya_hat_found_h","locale":"he","line_order":1,"content":"<strong>H</strong> היא האות השמינית — כמו <strong>Hat</strong> (כובע) ו-<strong>House</strong> (בית).","line_format":"safe_rich_text"},{"dialogue_key":"maya_hat_found_h","locale":"he","line_order":2,"content":"תודה! עכשיו אני לא רטובה.","line_format":"plain_text"},{"dialogue_key":"maya_island_sorted","locale":"he","line_order":0,"content":"האי מסודר! <strong>I</strong> כבר לא נראית כמו <strong>1</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"maya_island_sorted","locale":"he","line_order":1,"content":"<strong>I</strong> היא האות התשיעית — כמו <strong>Ice</strong> (קרח) ו-<strong>Island</strong> (אי).","line_format":"safe_rich_text"},{"dialogue_key":"maya_island_sorted","locale":"he","line_order":2,"content":"נשארה רק אות אחת אחרונה לפני הסיום!","line_format":"plain_text"},{"dialogue_key":"maya_letter_island_chaos","locale":"he","line_order":0,"content":"על אי האותיות, כל האותיות שלמדנו מתערבבות בערבוביה!","line_format":"plain_text"},{"dialogue_key":"maya_letter_island_chaos","locale":"he","line_order":1,"content":"האי חושב ש-<strong>I</strong> נראית כמו המספר <strong>1</strong> — ובלבל את כולם.","line_format":"safe_rich_text"},{"dialogue_key":"maya_letter_island_chaos","locale":"he","line_order":2,"content":"לכו לאי, סדרו את הבלגן בהתאמת מילים ובסידור אותיות, ומצאו את <strong>I</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_lost_hat_h","locale":"he","line_order":0,"content":"איבדתי את הכובע שלי! באנגלית זה <strong>HAT</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"maya_lost_hat_h","locale":"he","line_order":1,"content":"בלי האות <strong>H</strong>, הכובע הפך ל-<strong>_AT</strong> — וחתול שמח ישב עליו בגשם!","line_format":"safe_rich_text"},{"dialogue_key":"maya_lost_hat_h","locale":"he","line_order":2,"content":"לכו לכיכר הגשומה, סדרו את האותיות, ומצאו את <strong>H</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_welcome_runaway_a","locale":"he","line_order":0,"content":"שלום! אני מאיה, מורת האנגלית של <strong>ממלכת האותיות</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_welcome_runaway_a","locale":"he","line_order":1,"content":"היום נלמד את האות הראשונה באלף-בית — <strong>A</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_welcome_runaway_a","locale":"he","line_order":2,"content":"אבל יש בעיה דחופה: האות <strong>A</strong> בורחת! היא חושבת שהיא מלכת כל האלף-בית.","line_format":"safe_rich_text"},{"dialogue_key":"maya_welcome_runaway_a","locale":"he","line_order":3,"content":"לכו ללוח בכיתה, ציירו את האות <strong>A</strong>, ותפסו אותה לפני שהיא תעוף לשכונה הסמוכה!","line_format":"safe_rich_text"},{"dialogue_key":"maya_word_hero_graduation","locale":"he","line_order":0,"content":"מזל טוב! למדתם את האותיות <strong>A</strong> עד <strong>J</strong>!","line_format":"safe_rich_text"},{"dialogue_key":"maya_word_hero_graduation","locale":"he","line_order":1,"content":"אתם רשמית <strong>גיבורי המילים</strong> של ממלכת האנגלית!","line_format":"safe_rich_text"},{"dialogue_key":"maya_word_hero_graduation","locale":"he","line_order":2,"content":"קחו את תג הגיבור — וזכרו: כל מילה באנגלית מתחילה באות אחת מהאותיות שלמדתם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
